import{_ as o,o as t,c,a2 as d}from"./chunks/framework.CdvW4CUT.js";const g=JSON.parse('{"title":"Processor Bytecode Transformation & Network Sync Mechanics","description":"","frontmatter":{},"headers":[],"relativePath":"en/1.21.1/sync/processor-and-network.md","filePath":"en/1.21.1/sync/processor-and-network.md"}'),n={name:"en/1.21.1/sync/processor-and-network.md"};function a(i,e,r,s,l,y){return t(),c("div",null,[...e[0]||(e[0]=[d('<h1 id="processor-bytecode-transformation-network-sync-mechanics" tabindex="-1">Processor Bytecode Transformation &amp; Network Sync Mechanics <a class="header-anchor" href="#processor-bytecode-transformation-network-sync-mechanics" aria-label="Permalink to &quot;Processor Bytecode Transformation &amp; Network Sync Mechanics&quot;">​</a></h1><p>This page explains the low-level implementation of <code>module.sync</code> and <code>module.sync:processor</code> on NeoForge 1.21.1, helping you understand how zero-boilerplate registration works and how to debug complex inheritance, cross-dimension, or custom network setups.</p><h2 id="processor-bytecode-injection-icoremod-mode" tabindex="-1">Processor &amp; Bytecode Injection (<code>ICoreMod</code> Mode) <a class="header-anchor" href="#processor-bytecode-injection-icoremod-mode" aria-label="Permalink to &quot;Processor &amp; Bytecode Injection (`ICoreMod` Mode)&quot;">​</a></h2><p>When depending on <code>anvillib-sync-neoforge-1.21.1</code> in Maven/Gradle, <code>anvillib-sync-processor-neoforge-1.21.1</code> is <strong>automatically nested and bundled</strong> via <code>slimJarJar</code>—no manual processor dependency is needed.</p><p>On NeoForge 1.21.1 (FML Loader 4.0.x), before newer <code>ClassProcessor</code> SPIs existed, <code>module.sync:processor</code> registers an ASM <code>ITransformer&lt;ClassNode&gt;</code> class transformer with ModLauncher via the standard SPI file:</p><p><code>META-INF/services/net.neoforged.neoforgespi.coremod.ICoreMod</code> -&gt; <code>dev.anvilcraft.lib.v2.sync.transform.SyncClassProcessor</code></p><p>registers an ASM <code>ITransformer&lt;ClassNode&gt;</code> class transformer with ModLauncher.</p><h3 id="startup-timeline-bytecode-rewrites" tabindex="-1">Startup Timeline &amp; Bytecode Rewrites <a class="header-anchor" href="#startup-timeline-bytecode-rewrites" aria-label="Permalink to &quot;Startup Timeline &amp; Bytecode Rewrites&quot;">​</a></h3><ol><li><strong>Mod discovery phase (before target classes load)</strong>: <ul><li><code>SyncTargetIndex</code> statically scans <code>LoadingModList</code> for internal names and <code>SyncDirection</code>s of all <code>@Sync</code>-annotated classes.</li><li><code>LazySyncTargetIndex</code> statically scans owning class internal names for all <code>@LazySync</code>-annotated fields.</li></ul></li><li><strong>Class-load transformation phase (<code>SyncTransformer.transform</code>)</strong>: <ul><li>If the class is in <code>SyncTargetIndex</code>: <code>SyncBytecodeInjector</code> inspects all <strong><code>final SyncProxy</code></strong> fields and injects <code>proxy.setParent(this)</code>, <code>proxy.setFieldName(name)</code>, and <code>proxy.setDirection(classDir)</code> before every return in <code>&lt;init&gt;</code>; for <code>static final</code> fields, injects <code>proxy.setParent(Owner.class)</code> etc. at the end of <code>&lt;clinit&gt;</code> (creating <code>&lt;clinit&gt;</code> if absent).</li><li>If the class is in <code>LazySyncTargetIndex</code>: <code>LazySyncBytecodeInjector</code> injects <code>AnvilLibSync.LAZY_SYNC_MANAGER.track(this)</code> before every return in <code>&lt;init&gt;</code>, and <code>AnvilLibSync.LAZY_SYNC_MANAGER.trackStatic(Owner.class)</code> at the end of <code>&lt;clinit&gt;</code> for static <code>@LazySync</code> fields.</li></ul></li></ol><div class="tip custom-block"><p class="custom-block-title">Automatic GC &amp; Inheritance Support</p><ul><li><code>LazySyncManager</code> stores tracked instances and snapshots in Guava <code>MapMaker().weakKeys()</code> weak-keyed maps; unloaded <code>Entity</code>s or <code>BlockEntity</code>s without external strong references are automatically garbage-collected with <strong>no explicit unregister needed</strong>.</li><li><code>LazySyncManager</code> walks superclasses (<code>clazz -&gt; superclass -&gt; ...</code>) when collecting metadata, so subclasses automatically inherit and sync <code>@LazySync</code> fields declared on parent classes (provided both sides match the same <code>SyncRegisterEntry</code>).</li></ul></div><h2 id="config-sync-packet-routing-rules" tabindex="-1">Config Sync &amp; Packet Routing Rules <a class="header-anchor" href="#config-sync-packet-routing-rules" aria-label="Permalink to &quot;Config Sync &amp; Packet Routing Rules&quot;">​</a></h2><h3 id="_1-configuration-phase-unified-field-index-table" tabindex="-1">1. Configuration-Phase Unified Field Index Table <a class="header-anchor" href="#_1-configuration-phase-unified-field-index-table" aria-label="Permalink to &quot;1. Configuration-Phase Unified Field Index Table&quot;">​</a></h3><p>To avoid sending verbose <code>&quot;com.example.MyTile#manaPool&quot;</code> strings on every field update, the module uses a config compression table like RPC:</p><ul><li>After mod init (<code>FMLCommonSetupEvent</code>), <code>SyncConfigManager.compileContent()</code> scans all <code>final SyncProxy</code> fields in <code>@Sync</code> classes and all <code>@LazySync</code> fields, assigning incremental <code>int</code> IDs (<code>syncConfigId</code>).</li><li>When a player joins during Configuration, <code>AnvilLibSync.SyncConfig</code> sends <code>SyncConfigurationPayload(syncMap)</code>; the client writes it into <code>AnvilLibSyncClient.SYNC_CONFIG_MANAGER</code> and replies with <code>SyncConfigurationFinishPayload</code>.</li></ul><h3 id="_2-per-dimension-tracking-player-routing-sideutil" tabindex="-1">2. Per-Dimension &amp; Tracking-Player Routing (<code>SideUtil</code>) <a class="header-anchor" href="#_2-per-dimension-tracking-player-routing-sideutil" aria-label="Permalink to &quot;2. Per-Dimension &amp; Tracking-Player Routing (`SideUtil`)&quot;">​</a></h3><p>When the server sends a sync packet, <code>SideUtil.serverSend(...)</code> chooses the broadcast scope from <code>SyncRegisterEntry</code> to avoid unnecessary global broadcasts:</p><table tabindex="0"><thead><tr><th>Host Condition (<code>entry.dimension()</code> &amp; ID/Object Type)</th><th>NeoForge Send Target</th></tr></thead><tbody><tr><td><code>dimension == false</code> or <code>dimensionGetter == null</code> (e.g., <code>STATIC</code>)</td><td><code>PacketDistributor.sendToAllPlayers(packet)</code></td></tr><tr><td>Host ID is <code>BlockPos</code> (e.g., <code>BLOCK_ENTITY</code>)</td><td><code>PacketDistributor.sendToPlayersTrackingChunk(level, ChunkPos(pos), packet)</code></td></tr><tr><td>Host object is <code>Entity</code></td><td><code>PacketDistributor.sendToPlayersTrackingEntity(entity, packet)</code> followed by dimension send (note: source has no <code>return</code> here, so entities also fall through to <code>sendToPlayersInDimension</code>)</td></tr><tr><td>Other dimension-scoped objects</td><td><code>PacketDistributor.sendToPlayersInDimension(level, packet)</code></td></tr></tbody></table><p>Client-side sends (<code>C2S</code> / <code>BOTH</code>) uniformly call <code>PacketDistributor.sendToServer(...)</code>.</p><h3 id="_3-lazysyncpayload-anti-loop-suppression" tabindex="-1">3. <code>LazySyncPayload</code> &amp; Anti-Loop Suppression <a class="header-anchor" href="#_3-lazysyncpayload-anti-loop-suppression" aria-label="Permalink to &quot;3. `LazySyncPayload` &amp; Anti-Loop Suppression&quot;">​</a></h3><p>After <code>LazySyncManager</code> receives <code>LazySyncPayload</code> and writes fields back via <code>field.set(...)</code>, it <strong>immediately re-encodes the newly written value and overwrites its local <code>snap.put(configKey, encoded)</code></strong>. This prevents the next tick from mistaking the received update for a local change and ping-ponging it back.</p><h2 id="internal-api-network-payloads-overview" tabindex="-1">Internal API &amp; Network Payloads Overview <a class="header-anchor" href="#internal-api-network-payloads-overview" aria-label="Permalink to &quot;Internal API &amp; Network Payloads Overview&quot;">​</a></h2><p>Although most of these classes are <code>@ApiStatus.Internal</code>, understanding their roles helps when writing custom <code>SyncRegisterEntry</code>s or debugging packets:</p><h3 id="runtime-network-classes-dev-anvilcraft-lib-v2-sync" tabindex="-1">Runtime &amp; Network Classes (<code>dev.anvilcraft.lib.v2.sync.*</code>) <a class="header-anchor" href="#runtime-network-classes-dev-anvilcraft-lib-v2-sync" aria-label="Permalink to &quot;Runtime &amp; Network Classes (`dev.anvilcraft.lib.v2.sync.*`)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Class</th><th>Responsibilities &amp; Key Public Members</th></tr></thead><tbody><tr><td><code>AnvilLibSync</code></td><td>Mod entry (<code>MOD_ID = &quot;anvillib_sync&quot;</code>); holds <code>SYNC_MANAGER</code>, <code>SYNC_CONFIG_MANAGER</code>, <code>LAZY_SYNC_MANAGER</code>; registers server <code>ServerTickEvent.Post</code>, <code>ServerStoppedEvent</code>, and <code>SyncConfig</code> task</td></tr><tr><td><code>AnvilLibSyncClient</code></td><td>Client <code>@Mod(dist = Dist.CLIENT)</code> entry; holds client <code>SYNC_CONFIG_MANAGER</code>; drives <code>ClientTickEvent.Post</code> and clears client lazy tracking on <code>ClientPlayerNetworkEvent.LoggingOut</code></td></tr><tr><td><code>AnvilLibSyncNetwork</code></td><td>Auto-registers all bidirectional and config packets under <code>NETWORK_VERSION = &quot;1&quot;</code> via <code>NetworkRegistrar</code></td></tr><tr><td><code>SyncManager</code></td><td>Maintains <code>Class&lt;?&gt; -&gt; SyncRegisterEntry&lt;?, ?&gt;</code> lookups (<code>isAssignableFrom</code> matching) and immediate sync dispatch</td></tr><tr><td><code>LazySyncManager</code></td><td>Handles <code>@LazySync</code> diffing, grouped encoding, and anti-loop write-back (<code>AppliedField</code> record, <code>tickServer</code>/<code>tickClient</code>/<code>clearServer</code>/<code>clearClient</code>/<code>track</code>/<code>trackStatic</code>/<code>applyGrouped</code>)</td></tr><tr><td><code>SyncConfigManager</code></td><td>Scans <code>@Sync</code> bytecode fields and <code>@LazySync</code> fields via ASM, managing the bidirectional <code>String &lt;-&gt; int</code> config map</td></tr><tr><td><code>SideUtil</code></td><td>Provides <code>isServer()</code>, <code>registryAccess()</code>, <code>entityFinder</code>, <code>blockEntityFinder</code>, <code>createFriendlyByteBuf(ByteBuf)</code> (creates <code>RegistryFriendlyByteBuf</code> when registries exist), and <code>send</code> / <code>serverSend</code> / <code>clientSend</code></td></tr><tr><td><code>SyncPayload</code></td><td>Immediate single-<code>SyncProxy</code> bidirectional sync packet (<code>anvillib_sync:sync</code>)</td></tr><tr><td><code>LazySyncPayload</code></td><td>Host-batched lazy sync bidirectional packet (<code>anvillib_sync:lazy_sync</code>) with nested <code>FieldChange(String configKey, byte[] blob)</code></td></tr><tr><td><code>SyncConfigurationPayload</code> / <code>Finish</code></td><td>Configuration-phase config map sync packets (<code>anvillib_sync:sync_config</code> / <code>anvillib_sync:sync_config_finish</code>)</td></tr></tbody></table><h3 id="processor-bytecode-injection-classes-dev-anvilcraft-lib-v2-sync-transform" tabindex="-1">Processor Bytecode Injection Classes (<code>dev.anvilcraft.lib.v2.sync.transform</code>) <a class="header-anchor" href="#processor-bytecode-injection-classes-dev-anvilcraft-lib-v2-sync-transform" aria-label="Permalink to &quot;Processor Bytecode Injection Classes (`dev.anvilcraft.lib.v2.sync.transform`)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Class</th><th>Description</th></tr></thead><tbody><tr><td><code>SyncClassProcessor</code></td><td>Implements <code>ICoreMod</code> and exposes <code>SyncTransformer</code>, routing target classes to <code>@Sync</code> and <code>@LazySync</code> injectors</td></tr><tr><td><code>SyncTargetIndex</code> / <code>LazySyncTargetIndex</code></td><td>Pre-builds target class indices from <code>LoadingModList</code> annotation scan results</td></tr><tr><td><code>SyncBytecodeInjector</code> / <code>LazySyncBytecodeInjector</code></td><td>Pure ASM Tree API bytecode injectors appending registration and binding calls before <code>&lt;init&gt;</code> and <code>&lt;clinit&gt;</code> returns</td></tr></tbody></table>',26)])])}const h=o(n,[["render",a]]);export{g as __pageData,h as default};
